    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.arElementEClass, source, new String[]{"documentation", "An element that can be defined stand-alone, i.e. without being part of another element (except for packages of course).\r\n\r\nOpposed to packages, the elements are closed sets, i.e. that in a file based description, one ARElement needs to be described completely and cannot be extended or completed by another file.\r\n"});
        this.addAnnotation((ENamedElement)this.identifiableEClass, source, new String[]{"documentation", "Instances of this class can be referred to by their identifier (while adhering to namespace borders)."});
        this.addAnnotation((ENamedElement)this.identifiableEClass.getEOperations().get(0), source, new String[]{"body", "if (wrappedExtensions == null) {\n\twrappedExtensions = new WrappedExtensionsMap();\n}\nreturn wrappedExtensions;", "documentation", "Enables extensions to be stored on underlying AUTOSAR element, i.e. additional data which has not been foreseen by AUTOSAR metamodel designers. Such extensions can either be primitive values such as String, boolean, int, double, or complex values, i.e. EMF-based model fragments. Upon serialization, primitive extensions are always stored as SDG and SD objects inside the same ARXML file as the Identifiable they belong to. Complex extensions are also stored as SDG and SD objects inside the ARXML file if they are not directly or indirectly contained by a separate resource. If they do so then only a cross-document reference to this other resource is stored in the ARXML file."});
        this.addAnnotation((ENamedElement)this.getIdentifiable_ShortName(), source, new String[]{"documentation", "Use <shortName> to generate a short name for the context element, which enables it to be ** ."});
        this.addAnnotation((ENamedElement)this.getIdentifiable_LongName(), source, new String[]{"documentation", "Use <longName> to create a comprehensive name for the context element."});
        this.addAnnotation((ENamedElement)this.getIdentifiable_Desc(), source, new String[]{"documentation", "<desc> represents a general but brief description of the object in question."});
        this.addAnnotation((ENamedElement)this.getIdentifiable_Category(), source, new String[]{"documentation", "This element assigns a category to the parent element. The category can be used by a semantic checker in post-processes to ensure that the parent object is defined correctly i.e. has the right number of elements for example."});
        this.addAnnotation((ENamedElement)this.getIdentifiable_AdminData(), source, new String[]{"documentation", "<adminData> can be used to set administrative information for an element. This administration information is to be treated as metadata such as revision id or state of the file. There are basically four kinds of metadata\r\n\r\n* The language and/or used laguages.\r\n\r\n* Revision information covering e.g. revision number, state, release date, changes. Note that this information can be given in general as well as related to a particular company.\r\n\r\n* Document metadata specific for a company\r\n\r\n* Formatting controls that can affect layouts for example.\r\n\r\n* Revision information for the element."});
        this.addAnnotation((ENamedElement)this.getIdentifiable_Introduction(), source, new String[]{"documentation", "This represents more information about how the object in question is built or is used. Therefore it is a DocumentationBlock.\r\n\r\nIn this AUTOSAR Version it is intended to refer to external objexts which are not processed by AUTOSAR-tools."});
        this.addAnnotation((ENamedElement)this.getIdentifiable_Uuid(), source, new String[]{"documentation", "The purpose of this attribute is to provide a globally unique identifier for an instance of a metaclass. The values of this attribute should be globally unique strings prefixed by the type of identifier.  For example, to include a\r\nDCE UUID as defined by The Open Group, the UUID would be preceded by \"DCE:\". The values of this attribute may be used to support merging of different AUTOSAR models. \r\nThe form of the UUID (Universally Unique Identifier) is taken from a standard defined by the Open Group (was Open Software Foundation). This standard is widely used, including by Microsoft for COM (GUIDs) and by many companies for DCE, which is based on CORBA. The method for generating these 128-bit IDs is published in the standard and the effectiveness and uniqueness of the IDs is not in practice disputed.\r\nIf the id namespace is omitted, DCE is assumed. \r\nAn example is \"DCE:2fac1234-31f8-11b4-a222-08002b34c003\"."});
        this.addAnnotation((ENamedElement)this.getIdentifiable_AllExtensions(), source, new String[]{"suppressedGetVisibility", "true"});
        this.addAnnotation((ENamedElement)this.getIdentifiable_ContainedExtensions(), source, new String[]{"suppressedGetVisibility", "true"});
    }

